        return new AcceptedTurnCanonicalRefreshResult(true, held.Issues, JointPublication: held);
    }
    var joint = await PublishCurrentMortalJointRepairAsync(activeSnapshotContext, expectedTurn, snapshot);
    return new AcceptedTurnCanonicalRefreshResult(true, joint.Issues, joint.Plan, JointPublication: joint);

private async Task<AcceptedTurnValidationDisposition> ValidateMortalJointPostPublicationAsync(
    string source, ValidatedPendingTurnSnapshotContext frame, MortalJointRepairCanonicalRefresh publication,
    WoundAcceptedTurnOutputBindingResult? continuationOutput = null)
{
    if (publication.Disposition != MortalJointRepairPublicationDisposition.Committed ||
        !SameMortalJointOriginalFrame(publication.Frame, frame, frame.TurnNumber))
        return AcceptedTurnValidationDisposition.MortalJointRepairPublicationHeldBlocked;

AcceptedTurnValidationDisposition HeldWithFrozenIssues(IReadOnlyList<ValidationIssue> issues)
{
    _mortalJointInterfacePreparationHeld = true;
    foreach (var issue in issues) _logger.LogWarning("Selected joint I owning refusal: {Issue}", issue);
    return AcceptedTurnValidationDisposition.MortalJointRepairPublicationHeldBlocked;
}

